import AppKit
import CryptoKit
import ImageIO

/// Reading copies off the pasteboard, putting one back, and the PNG files behind image copies.
enum ClipboardPasteboard {
    /// A screenshot of a 6K display is about 10 MB as PNG; anything far beyond is not kept.
    static let maxImageBytes = 25_000_000

    /// Pasteboard markers password managers and similar tools set on content that must not be
    /// kept (see nspasteboard.org).
    private static let privateTypes = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword",
    ].map { NSPasteboard.PasteboardType($0) }

    enum Captured {
        case text(String)
        case files([URL])
        /// PNG or TIFF data as the source app wrote it.
        case image(Data)
    }

    /// What is on the pasteboard, or nil when it is private or nothing this history keeps.
    ///
    /// Files first: copying a file in Finder also offers its name as text and its icon as an image.
    /// Text before images: spreadsheets and word processors add a picture of the copied text.
    static func read(_ pasteboard: NSPasteboard) -> Captured? {
        let types = pasteboard.types ?? []
        guard !types.contains(where: privateTypes.contains) else { return nil }
        if let urls = pasteboard.readObjects(forClasses: [NSURL.self],
                                             options: [.urlReadingFileURLsOnly: true]) as? [URL], !urls.isEmpty {
            return .files(urls)
        }
        if let text = pasteboard.string(forType: .string), !text.isEmpty { return .text(text) }
        if let data = pasteboard.data(forType: .png) ?? pasteboard.data(forType: .tiff) { return .image(data) }
        return nil
    }

    /// Puts an item back on the pasteboard in its original form.
    static func write(_ item: ClipboardItem, imagesDirectory: URL, to pasteboard: NSPasteboard) {
        pasteboard.clearContents()
        switch item.kind {
        case .image:
            guard let file = item.imageFile,
                  let image = NSImage(contentsOf: imagesDirectory.appendingPathComponent(file)) else { return }
            pasteboard.writeObjects([image])
        case .file:
            pasteboard.writeObjects(item.filePaths.map { URL(fileURLWithPath: $0) as NSURL })
        case .text, .link, .email:
            pasteboard.setString(item.text, forType: .string)
        }
    }

    /// Saves copied image data as an owner-only PNG and describes it. Nil when it is not an image
    /// or too large to keep.
    static func storeImage(_ data: Data, in directory: URL, sourceApp: String?,
                           sourceBundleID: String?) -> ClipboardItem? {
        guard let bitmap = NSBitmapImageRep(data: data),
              let png = bitmap.representation(using: .png, properties: [:]),
              png.count <= maxImageBytes else { return nil }
        let id = UUID()
        let name = "\(id.uuidString).png"
        let url = directory.appendingPathComponent(name)
        do {
            try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
            try png.write(to: url, options: .atomic)
            try FileManager.default.setAttributes([.posixPermissions: 0o600], ofItemAtPath: url.path)
        } catch {
            NSLog("OneMac: could not save a copied image: \(error.localizedDescription)")
            return nil
        }
        let hash = SHA256.hash(data: png).map { String(format: "%02x", $0) }.joined()
        return ClipboardItem(id: id, kind: .image, text: "", sourceApp: sourceApp, sourceBundleID: sourceBundleID, imageFile: name,
                             pixelWidth: bitmap.pixelsWide, pixelHeight: bitmap.pixelsHigh,
                             byteCount: png.count, contentHash: hash)
    }

    /// Deletes PNGs no item refers to any more. Files younger than a minute are left alone: an
    /// image is written before the item that owns it is recorded.
    static func removeOrphanImages(in directory: URL, keeping names: Set<String>) {
        let files = (try? FileManager.default.contentsOfDirectory(
            at: directory, includingPropertiesForKeys: [.contentModificationDateKey])) ?? []
        for file in files where !names.contains(file.lastPathComponent) {
            let modified = (try? file.resourceValues(forKeys: [.contentModificationDateKey]))?.contentModificationDate
            if let modified, Date().timeIntervalSince(modified) > 60 {
                try? FileManager.default.removeItem(at: file)
            }
        }
    }

    /// A downscaled copy for the list and the preview, decoded without loading the full image.
    static func thumbnail(of url: URL, maxPixel: Int) -> NSImage? {
        guard let source = CGImageSourceCreateWithURL(url as CFURL, nil) else { return nil }
        let options: [CFString: Any] = [
            kCGImageSourceCreateThumbnailFromImageAlways: true,
            kCGImageSourceCreateThumbnailWithTransform: true,
            kCGImageSourceThumbnailMaxPixelSize: maxPixel,
        ]
        guard let image = CGImageSourceCreateThumbnailAtIndex(source, 0, options as CFDictionary) else { return nil }
        return NSImage(cgImage: image, size: NSSize(width: image.width, height: image.height))
    }
}
